// API probe core, shared by every context (service worker via importScripts, pages via <script>).
// Plain JS, no build step. Walks catalog.json (generated by the e2e test from src/shared/extension-api-catalog.ts) and
// records, per namespace and member, whether it exists on `chrome` and on `browser`, plus the outcome of a few harmless calls.
;(function (root) {
  const CALL_TIMEOUT = 2000
  const g = root

  const short = (v) => {
    try {
      const s = typeof v === 'undefined' ? 'undefined' : JSON.stringify(v)
      return s.length > 160 ? s.slice(0, 160) + '...' : s
    } catch {
      return String(v)
    }
  }
  const errText = (e) => (e && e.message ? e.message : String(e))

  /** Resolves a dotted path on `root[name]`; returns { found, value, error }. Lazy getters can throw, hence the try. */
  function resolvePath(obj, path) {
    let cur = obj
    try {
      for (const part of path.split('.')) {
        if (cur === null || cur === undefined) return { found: false }
        if (!(part in Object(cur))) return { found: false }
        cur = cur[part]
      }
      return cur === undefined ? { found: false } : { found: true, value: cur }
    } catch (e) {
      return { found: false, error: errText(e) }
    }
  }

  function describe(obj, name) {
    try {
      if (obj === null || obj === undefined || !(name in Object(obj))) return null
      const v = obj[name]
      return v === null ? 'null' : typeof v
    } catch (e) {
      return 'getter-throws: ' + errText(e)
    }
  }

  /** Exercises an event object. Returns 'ok' or a list of the failing methods. */
  // Touching these in the service worker kills the whole Signet process (SIGSEGV in main, macOS, Electron 45.1): the native
  // implementations need hardware services Electron never starts. They are reported as skipped unless probe-config.json lists them
  // in `unsafe` (calls by label, events as `event:<namespace>.<name>`). SIGNET_PROBE_UNSAFE=a,b feeds that list in the e2e spec.
  const CRASHERS = {
    'system.cpu.getInfo': 'native system.cpu crashes the browser process',
    'system.memory.getInfo': 'native system.memory crashes the browser process',
    'system.display.getInfo': 'native system.display crashes the browser process',
    'system.storage.getInfo': 'native system.storage crashes the browser process'
  }
  const EVENT_CRASHERS = ['system.storage.', 'printerProvider.']
  let unsafe = []

  function probeEvent(ev, path) {
    if (EVENT_CRASHERS.some((p) => path.startsWith(p)) && !unsafe.includes('event:' + path)) return 'skipped (crashes the browser process)'
    if (ev === null || typeof ev !== 'object') return 'not-an-object'
    const fn = () => {}
    const problems = []
    const attempt = (label, f) => {
      try {
        return f()
      } catch (e) {
        problems.push(label + ': ' + errText(e))
      }
    }
    if (typeof ev.addListener !== 'function') problems.push('addListener missing')
    else {
      attempt('addListener', () => ev.addListener(fn))
      if (typeof ev.hasListener !== 'function') problems.push('hasListener missing')
      else attempt('hasListener', () => ev.hasListener(fn))
      if (typeof ev.hasListeners !== 'function') problems.push('hasListeners missing')
      else attempt('hasListeners', () => ev.hasListeners())
      if (typeof ev.removeListener !== 'function') problems.push('removeListener missing')
      else attempt('removeListener', () => ev.removeListener(fn))
    }
    return problems.length ? problems.join('; ') : 'ok'
  }

  function members(spec) {
    const out = []
    for (const m of spec.methods || []) out.push({ kind: 'method', name: m })
    for (const e of spec.events || []) out.push({ kind: 'event', name: e })
    for (const c of Object.keys(spec.constants || {})) out.push({ kind: 'constant', name: c })
    for (const k of spec.classes || []) out.push({ kind: 'class', name: k })
    return out
  }

  function walk(catalog, prefix, into, apis) {
    for (const [name, spec] of Object.entries(catalog)) {
      const path = prefix + name
      console.log('[probe] walk ' + path)
      const row = { unsupported: !!spec.unsupported, contentScriptOnly: !!spec.contentScriptOnly, members: {} }
      for (const api of ['chrome', 'browser']) {
        const target = apis[api]
        const r = target ? resolvePath(target, path) : { found: false }
        row[api] = r.found ? typeof r.value : r.error ? 'getter-throws: ' + r.error : null
        row[api + 'Obj'] = r.found ? r.value : undefined
      }
      row.same = row.chromeObj !== undefined && row.chromeObj === row.browserObj
      for (const m of members(spec)) {
        const cell = { kind: m.kind }
        for (const api of ['chrome', 'browser']) {
          const holder = row[api + 'Obj']
          cell[api] = describe(holder, m.name)
          if (m.kind === 'event' && holder && cell[api] === 'object') {
            console.log('[probe] event ' + api + ' ' + path + '.' + m.name)
            cell[api + 'Event'] = probeEvent(holder[m.name], path + '.' + m.name)
          }
        }
        row.members[m.name] = cell
      }
      into[path] = row
      if (spec.children) walk(spec.children, path + '.', into, apis)
    }
  }

  const strip = (rows) => {
    for (const r of Object.values(rows)) {
      delete r.chromeObj
      delete r.browserObj
    }
    return rows
  }

  function withTimeout(label, fn) {
    console.log('[probe] call ' + label)
    return new Promise((resolve) => {
      let done = false
      const finish = (r) => {
        if (!done) {
          done = true
          clearTimeout(timer)
          resolve(r)
        }
      }
      const timer = setTimeout(() => finish({ status: 'timeout' }), CALL_TIMEOUT)
      try {
        const p = fn()
        if (p && typeof p.then === 'function')
          p.then(
            (v) => finish({ status: 'resolved', value: short(v) }),
            (e) => finish({ status: 'rejected', message: errText(e) })
          )
        else finish({ status: 'resolved', value: short(p) })
      } catch (e) {
        finish({ status: 'threw', message: errText(e) })
      }
    })
  }

  /** Harmless calls: [dotted function path, thunk]. A path whose function is absent is recorded as `missing`. */
  function callList(c) {
    const sess = 'probe_' + Math.random().toString(36).slice(2, 8)
    return [
      ['runtime.getPlatformInfo', () => c.runtime.getPlatformInfo()],
      ['runtime.getManifest', () => c.runtime.getManifest().name],
      ['runtime.getContexts', () => c.runtime.getContexts({})],
      ['runtime.setUninstallURL', () => c.runtime.setUninstallURL('')],
      ['runtime.requestUpdateCheck', () => c.runtime.requestUpdateCheck()],
      [
        'runtime.getPlatformInfo (callback)',
        () => new Promise((res, rej) => c.runtime.getPlatformInfo((v) => (c.runtime.lastError ? rej(c.runtime.lastError) : res(v))))
      ],
      ['storage.session.set', () => c.storage.session.set({ [sess]: 1 })],
      ['storage.session.get', () => c.storage.session.get(sess)],
      ['storage.local.set', () => c.storage.local.set({ probeLocalOnly: sess })],
      ['storage.sync.get', () => c.storage.sync.get('probeLocalOnly')],
      ['storage.managed.get', () => c.storage.managed.get(null)],
      ['idle.queryState', () => c.idle.queryState(60)],
      ['alarms.getAll', () => c.alarms.getAll()],
      ['alarms.create', () => c.alarms.create(sess, { delayInMinutes: 60 })],
      ['alarms.clear', () => c.alarms.clear(sess)],
      ['commands.getAll', () => c.commands.getAll()],
      ['permissions.getAll', () => c.permissions.getAll()],
      ['permissions.contains', () => c.permissions.contains({ permissions: ['bookmarks'] })],
      ['tabs.query', () => c.tabs.query({})],
      ['tabs.getCurrent', () => c.tabs.getCurrent()],
      ['windows.getAll', () => c.windows.getAll()],
      ['windows.getCurrent', () => c.windows.getCurrent()],
      ['management.getSelf', () => c.management.getSelf().then((s) => s.name)],
      ['management.getAll', () => c.management.getAll().then((a) => a.length)],
      ['declarativeNetRequest.getEnabledRulesets', () => c.declarativeNetRequest.getEnabledRulesets()],
      ['declarativeNetRequest.getDynamicRules', () => c.declarativeNetRequest.getDynamicRules()],
      ['userScripts.getScripts', () => c.userScripts.getScripts()],
      ['system.cpu.getInfo', () => c.system.cpu.getInfo()],
      ['system.memory.getInfo', () => c.system.memory.getInfo()],
      ['system.display.getInfo', () => c.system.display.getInfo()],
      ['system.storage.getInfo', () => c.system.storage.getInfo()],
      ['power.requestKeepAwake', () => c.power.requestKeepAwake('system')],
      ['power.releaseKeepAwake', () => c.power.releaseKeepAwake()],
      ['cookies.getAllCookieStores', () => c.cookies.getAllCookieStores()],
      ['i18n.getUILanguage', () => c.i18n.getUILanguage()],
      ['i18n.getAcceptLanguages', () => c.i18n.getAcceptLanguages()],
      ['offscreen.hasDocument', () => c.offscreen.hasDocument()],
      ['privacy.network.webRTCIPHandlingPolicy.get', () => c.privacy.network.webRTCIPHandlingPolicy.get({})],
      ['proxy.settings.get', () => c.proxy.settings.get({})],
      ['contextMenus.removeAll', () => c.contextMenus.removeAll()],
      ['notifications.getAll', () => c.notifications.getAll()],
      ['notifications.getPermissionLevel', () => c.notifications.getPermissionLevel()],
      ['topSites.get', () => c.topSites.get()],
      ['downloads.search', () => c.downloads.search({})],
      ['bookmarks.getTree', () => c.bookmarks.getTree()],
      ['history.search', () => c.history.search({ text: '', maxResults: 1 })],
      ['sessions.getRecentlyClosed', () => c.sessions.getRecentlyClosed()],
      ['fontSettings.getFontList', () => c.fontSettings.getFontList()],
      ['tts.getVoices', () => c.tts.getVoices()],
      ['scripting.getRegisteredContentScripts', () => c.scripting.getRegisteredContentScripts()],
      ['sidePanel.getOptions', () => c.sidePanel.getOptions({})],
      ['sidePanel.getPanelBehavior', () => c.sidePanel.getPanelBehavior()],
      ['tabGroups.query', () => c.tabGroups.query({})],
      ['action.getTitle', () => c.action.getTitle({})],
      ['action.getBadgeText', () => c.action.getBadgeText({})],
      ['action.getUserSettings', () => c.action.getUserSettings()],
      ['action.isEnabled', () => c.action.isEnabled()],
      ['extension.getViews', () => c.extension.getViews()],
      ['extension.isAllowedIncognitoAccess', () => c.extension.isAllowedIncognitoAccess()],
      ['browsingData.settings', () => c.browsingData.settings()],
      ['identity.getRedirectURL', () => c.identity.getRedirectURL('cb')],
      ['contentSettings.cookies.get', () => c.contentSettings.cookies.get({ primaryUrl: 'https://example.com/' })],
      ['declarativeContent.onPageChanged.getRules', () => c.declarativeContent.onPageChanged.getRules()],
      ['webNavigation.getAllFrames', () => c.webNavigation.getAllFrames({ tabId: 0 })],
      ['dns.resolve', () => c.dns.resolve('localhost')],
      ['readingList.query', () => c.readingList.query({})]
    ]
  }

  async function runCalls(c) {
    const out = {}
    for (const [label, thunk] of callList(c)) {
      if (CRASHERS[label] && !unsafe.includes(label)) {
        out[label] = { status: 'skipped', message: CRASHERS[label] }
        continue
      }
      const fnPath = label.replace(/ \(.*\)$/, '')
      const parts = fnPath.split('.')
      const owner = resolvePath(c, parts.slice(0, -1).join('.'))
      // A missing namespace or function is `missing`, not an exception: that is exactly the gap we want to see.
      if (!owner.found) out[label] = { status: 'missing', message: 'namespace absent' }
      else if (typeof Object(owner.value)[parts[parts.length - 1]] !== 'function' && !/\.on[A-Z]/.test(fnPath))
        out[label] = { status: 'missing', message: 'function absent' }
      else out[label] = await withTimeout(label, thunk)
    }
    return out
  }

  async function loadCatalog() {
    const r = await fetch(g.chrome.runtime.getURL('catalog.json'))
    if (!r.ok) throw new Error('catalog.json: HTTP ' + r.status)
    return r.json()
  }

  async function loadConfig() {
    try {
      const r = await fetch(g.chrome.runtime.getURL('probe-config.json'))
      return r.ok ? await r.json() : {}
    } catch {
      return {}
    }
  }

  /** Runs the whole probe for one context and returns its report. */
  async function runProbe(context) {
    const report = { context, startedAt: Date.now(), errors: [] }
    try {
      const c = g.chrome
      const b = g.browser
      report.hasChrome = typeof c !== 'undefined'
      report.hasBrowser = typeof b !== 'undefined'
      report.browserIsChrome = report.hasChrome && report.hasBrowser ? b === c : null
      report.chromeFrozen = report.hasChrome ? Object.isFrozen(c) : null
      report.chromeKeys = report.hasChrome ? Object.keys(c).sort() : []
      report.browserKeys = report.hasBrowser ? Object.keys(b).sort() : []
      report.extensionId = report.hasChrome && c.runtime ? c.runtime.id : null
      report.href = (g.location && g.location.href) || null
      report.userAgent = (g.navigator && g.navigator.userAgent) || null
      report.contextIsolated = typeof g.window !== 'undefined' ? true : null
      unsafe = (await loadConfig()).unsafe || []
      let catalog
      try {
        catalog = await loadCatalog()
      } catch (e) {
        report.errors.push({ kind: 'catalog', message: errText(e) })
        catalog = {}
      }
      const rows = {}
      walk(catalog, '', rows, { chrome: c, browser: b })
      report.namespaces = strip(rows)
      report.calls = report.hasChrome ? await runCalls(c) : {}
    } catch (e) {
      report.errors.push({ kind: 'probe', message: errText(e) })
    }
    report.finishedAt = Date.now()
    return report
  }

  root.__probe = { runProbe, resolvePath }
})(typeof self !== 'undefined' ? self : globalThis)
